import { WORK_NAME_MOCK } from '../WorkNameMapping/mockData';
export const deriveNameStatus = (completed) => completed ? 'COMPLETED' : 'NOT_STARTED';
export const isWorkTypeCompleted = (wt) => wt.workNames.length > 0 && wt.workNames.every((n) => n.completed);
export const FIXED_WORKFLOW_ORDER = [
    'Structure',
    'Partition Wall',
    'Electrical Wall Pipe',
    'Concealed Plumbing',
    'Apartment Plastering',
    'Staircase Plastering',
    'Outer Plastering',
    'Outer Plumbing',
    'Wiring',
    'Apartment Painting',
    'Staircase Painting',
    'Outer Painting',
];
const today = () => new Date().toISOString();
const toWorkNameState = (name) => ({
    name,
    completed: false,
    progress: 0,
    completedDate: null,
    lastUpdated: null,
    remarks: '',
});
const toWorkTypeState = (workType, names) => ({
    id: `${workType}`,
    title: workType,
    workNames: names.map(toWorkNameState),
    startedAt: null,
    pausedAt: null,
    resumedAt: null,
    lastUpdated: null,
});
const collectWorkTypeNames = (mock, workType) => {
    const names = [];
    mock.forEach((section) => {
        section.work_types.forEach((wt) => {
            if (wt.work_type === workType) {
                names.push(...wt.work_names);
            }
        });
    });
    return names;
};
const uniqueWorkTypeNames = (mock) => {
    const map = {};
    mock.forEach((section) => {
        section.work_types.forEach((wt) => {
            if (!map[wt.work_type]) {
                map[wt.work_type] = [...wt.work_names];
            }
            else {
                const existing = new Set(map[wt.work_type]);
                wt.work_names.forEach((n) => {
                    if (!existing.has(n))
                        map[wt.work_type].push(n);
                });
            }
        });
    });
    return map;
};
const WORKFLOW_WORK_TYPE_MAP = {
    Structure: [
        'Column Foundation',
        'Basement',
        'Plinth Beam',
        'Floor Roof',
        'Column Extension',
    ],
    'Partition Wall': ['Apartment Partition', 'Staircase Partition', 'Lift Partition'],
    'Electrical Wall Pipe': ['Apartment Wall Pipe', 'Staircase Wall Pipe'],
    'Concealed Plumbing': ['Outer Side Plumbing', 'Ring Line Plumbing'],
    'Apartment Plastering': ['Apartment Plastering'],
    'Staircase Plastering': ['Staircase Plastering', 'Lift Plastering'],
    'Outer Plastering': ['Outer Plastering'],
    'Outer Plumbing': ['Outer Side Plumbing', 'Ring Line Plumbing'],
    Wiring: ['Apartment Wiring', 'Staircase Wiring', 'Lift Wiring'],
    'Apartment Painting': ['Apartment Painting'],
    'Staircase Painting': ['Staircase Painting', 'Lift Painting'],
    'Outer Painting': ['Outer Painting'],
};
/**
 * Generates the workflow tree from the existing Work Name mock data.
 * The workflow categories are fixed; only the work types inside them
 * are collected automatically from the mock.
 */
export const generateWorkflows = () => {
    const allWorkTypeNames = uniqueWorkTypeNames(WORK_NAME_MOCK);
    return FIXED_WORKFLOW_ORDER.map((workflowName) => {
        const workTypeNames = WORKFLOW_WORK_TYPE_MAP[workflowName] || [];
        const workTypes = workTypeNames
            .map((wt) => {
            const names = collectWorkTypeNames(WORK_NAME_MOCK, wt);
            if (names.length === 0 && allWorkTypeNames[wt]) {
                names.push(...allWorkTypeNames[wt]);
            }
            if (names.length === 0)
                return null;
            return toWorkTypeState(wt, names);
        })
            .filter((wt) => wt !== null);
        return {
            id: workflowName,
            name: workflowName,
            workTypes,
            status: 'NOT_STARTED',
            startDate: null,
            pauseDate: null,
            resumeDate: null,
            lastUpdated: null,
        };
    }).filter((wf) => wf.workTypes.length > 0);
};
export const computeWorkTypeProgress = (wt) => {
    if (wt.workNames.length === 0)
        return 0;
    const completed = wt.workNames.filter((n) => n.completed).length;
    return Math.round((completed / wt.workNames.length) * 100);
};
export const computeWorkflowProgress = (wf) => {
    if (wf.workTypes.length === 0)
        return 0;
    const sum = wf.workTypes.reduce((acc, wt) => acc + computeWorkTypeProgress(wt), 0);
    return Math.round(sum / wf.workTypes.length);
};
export const computeOverallProgress = (workflows) => {
    if (workflows.length === 0)
        return 0;
    const sum = workflows.reduce((acc, wf) => acc + computeWorkflowProgress(wf), 0);
    return Math.round(sum / workflows.length);
};
/**
 * Workflow status derived automatically from completion:
 * all work types completed            -> COMPLETED
 * some work types completed/in progress -> IN_PROGRESS
 * nothing started (0% everywhere)     -> NOT_STARTED
 * Manual PAUSED / STOPPED states are preserved by the caller.
 */
export const deriveWorkflowStatus = (wf) => {
    const total = wf.workTypes.length;
    if (total === 0)
        return 'NOT_STARTED';
    const done = wf.workTypes.filter(isWorkTypeCompleted).length;
    if (done === total)
        return 'COMPLETED';
    const anyStarted = wf.workTypes.some((wt) => wt.workNames.some((n) => (n.progress || 0) > 0));
    if (!anyStarted)
        return 'NOT_STARTED';
    return 'IN_PROGRESS';
};
export const computeOverallStats = (workflows) => {
    const allWorkTypes = workflows.reduce((acc, wf) => acc.concat(wf.workTypes), []);
    const allNames = allWorkTypes.reduce((acc, wt) => acc.concat(wt.workNames), []);
    const total = allNames.length;
    const completedNames = allNames.filter((n) => n.completed).length;
    const completedTypes = allWorkTypes.filter(isWorkTypeCompleted).length;
    const inProgress = workflows.filter((wf) => wf.status === 'IN_PROGRESS').length;
    const paused = workflows.filter((wf) => wf.status === 'PAUSED').length;
    const notStarted = workflows.filter((wf) => wf.status === 'NOT_STARTED').length;
    const overall = computeOverallProgress(workflows);
    return {
        totalWorkTypes: allWorkTypes.length,
        completed: completedTypes,
        inProgress,
        paused,
        notStarted,
        overall,
        completedNames,
        remainingNames: total - completedNames,
    };
};
